import{_ as t,o as l,c as e,a2 as i}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"AI 视频包装保真：参考图与成片不一致怎么解决","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"method/brand-consistency.md","filePath":"method/brand-consistency.md","lastUpdated":1787714366000}'),n={name:"method/brand-consistency.md"};function s(r,a,o,d,p,h){return l(),e("div",null,[...a[0]||(a[0]=[i(`<h1 id="ai-视频包装保真-参考图与成片不一致怎么解决" tabindex="-1">AI 视频包装保真：参考图与成片不一致怎么解决 <a class="header-anchor" href="#ai-视频包装保真-参考图与成片不一致怎么解决" aria-label="Permalink to &quot;AI 视频包装保真：参考图与成片不一致怎么解决&quot;">​</a></h1><p>给了产品参考图，生成视频里的包装仍然变形、改字或换版式，不一定是 Prompt 写得不够好。更根本的原因是：<strong>多数视频模型把参考图当成视觉条件，而不是必须逐像素保留的产品资产。</strong></p><p>这篇解决四个具体问题：</p><ol><li>为什么参考图里的包装会在视频中漂移。</li><li>哪些问题可以在生成阶段改善。</li><li>什么时候应该停止重生成，改用后期合成。</li><li>如何建立一条能交付商业广告的产品保真流程。</li></ol><h2 id="先判断-你需要-像-还是需要-准确" tabindex="-1">先判断：你需要“像”，还是需要“准确” <a class="header-anchor" href="#先判断-你需要-像-还是需要-准确" aria-label="Permalink to &quot;先判断：你需要“像”，还是需要“准确”&quot;">​</a></h2><p>这是决定工作流的第一步。</p><table tabindex="0"><thead><tr><th>交付要求</th><th>可以接受的结果</th><th>推荐方案</th></tr></thead><tbody><tr><td>概念片、提案样片</td><td>包装轮廓、主色和品牌气质相似</td><td>参考图 + 图生视频</td></tr><tr><td>社交媒体内容</td><td>Logo、主视觉和瓶型正确，小字不要求可读</td><td>受控图生视频 + 局部修复</td></tr><tr><td>电商、TVC、客户终稿</td><td>Logo、文字、版式、规格、颜色都必须准确</td><td>AI 生成镜头 + 后期贴图或 3D 合成</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">商用准确不能只靠 Prompt</p><p>Logo、品名、净含量、配料文字、条码和包装版式属于确定性信息。生成模型擅长合成“看起来像包装的画面”，不擅长逐帧保存这些信息。只要客户会拿实物逐项对照，就要预留合成环节。</p></div><h2 id="为什么上传参考图仍然会画错" tabindex="-1">为什么上传参考图仍然会画错 <a class="header-anchor" href="#为什么上传参考图仍然会画错" aria-label="Permalink to &quot;为什么上传参考图仍然会画错&quot;">​</a></h2><h3 id="原因一-模型在重绘-而不是移动原图" tabindex="-1">原因一：模型在重绘，而不是移动原图 <a class="header-anchor" href="#原因一-模型在重绘-而不是移动原图" aria-label="Permalink to &quot;原因一：模型在重绘，而不是移动原图&quot;">​</a></h3><p>图生视频并不是把参考图中的产品直接做平移、旋转。模型会根据首帧和运动描述预测后续画面，每一帧都可能重新解释包装细节。文字、Logo 和细线版式最容易在这个过程中被改写。</p><h3 id="原因二-单张图没有提供被遮挡的部分" tabindex="-1">原因二：单张图没有提供被遮挡的部分 <a class="header-anchor" href="#原因二-单张图没有提供被遮挡的部分" aria-label="Permalink to &quot;原因二：单张图没有提供被遮挡的部分&quot;">​</a></h3><p>参考图只有正面，Prompt 却要求产品旋转到侧面或背面时，模型只能自行补全看不到的信息。包装转得越多，虚构的内容越多。</p><h3 id="原因三-动作和运镜增加了约束难度" tabindex="-1">原因三：动作和运镜增加了约束难度 <a class="header-anchor" href="#原因三-动作和运镜增加了约束难度" aria-label="Permalink to &quot;原因三：动作和运镜增加了约束难度&quot;">​</a></h3><p>快速旋转、手部抓取、液体飞溅、强景深变化和复杂运镜，会同时改变产品的形状、遮挡、反光和透视。模型需要兼顾的变量越多，包装一致性越差。</p><h3 id="原因四-提示词之间存在竞争" tabindex="-1">原因四：提示词之间存在竞争 <a class="header-anchor" href="#原因四-提示词之间存在竞争" aria-label="Permalink to &quot;原因四：提示词之间存在竞争&quot;">​</a></h3><p>当一条 Prompt 同时要求复杂场景、人物动作、特殊光效、镜头运动和产品展示时，包装保真只是众多目标之一。参考图权重不足或描述冲突时，模型会优先完成更显眼的动作与画面风格。</p><h2 id="推荐工作流" tabindex="-1">推荐工作流 <a class="header-anchor" href="#推荐工作流" aria-label="Permalink to &quot;推荐工作流&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>包装设计稿 / 产品实拍</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>制作包装完全正确的关键帧</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>按镜头拆分，逐条做受控图生视频</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>筛选结构和运动稳定的版本</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>跟踪并覆盖正确包装</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>补反光、遮挡、景深与颗粒</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>逐帧检查并交付</span></span></code></pre></div><p>这条流程的关键是把两类任务分开：</p><ul><li><strong>AI 负责</strong>：场景、氛围、运动、光线和难以实拍的视觉效果。</li><li><strong>确定性工具负责</strong>：Logo、文字、包装版式和最终品牌资产。</li></ul><h2 id="第一步-准备合格的参考素材" tabindex="-1">第一步：准备合格的参考素材 <a class="header-anchor" href="#第一步-准备合格的参考素材" aria-label="Permalink to &quot;第一步：准备合格的参考素材&quot;">​</a></h2><p>不要只把客户从聊天软件发来的低清产品图直接丢给模型。生成前至少准备：</p><ul><li>高分辨率正面产品图，包装文字清晰、没有压缩噪点。</li><li>透明底产品图或干净背景产品图，便于制作首帧。</li><li>包装设计展开稿，后期贴图时使用。</li><li>需要旋转展示时，补齐侧面、背面和顶部参考。</li><li>品牌标准色、Logo 矢量文件和禁用规则。</li></ul><p>所有参考图中的包装版本必须一致。新旧包装、不同规格或不同语言版本混在一起，会让模型得到互相冲突的信号。</p><h2 id="第二步-先做对的关键帧-再让它动" tabindex="-1">第二步：先做对的关键帧，再让它动 <a class="header-anchor" href="#第二步-先做对的关键帧-再让它动" aria-label="Permalink to &quot;第二步：先做对的关键帧，再让它动&quot;">​</a></h2><p>优先使用“先静帧、后视频”的两段式流程：</p><ol><li>用真实产品图和目标场景合成一张准确首帧。</li><li>检查瓶型、包装比例、Logo 位置和主视觉。</li><li>将通过检查的首帧送入图生视频。</li><li>有首尾帧控制时，同时提供准确尾帧，减少结尾漂移。</li></ol><p>不要在包装还没对的情况下直接生成视频。首帧错误会被带进整段视频，后面再靠 Prompt 修正的成功率很低。</p><h2 id="第三步-把镜头设计成-容易保真" tabindex="-1">第三步：把镜头设计成“容易保真” <a class="header-anchor" href="#第三步-把镜头设计成-容易保真" aria-label="Permalink to &quot;第三步：把镜头设计成“容易保真”&quot;">​</a></h2><h3 id="优先选择的镜头" tabindex="-1">优先选择的镜头 <a class="header-anchor" href="#优先选择的镜头" aria-label="Permalink to &quot;优先选择的镜头&quot;">​</a></h3><ul><li>产品固定，镜头缓慢推进或轻微横移。</li><li>包装正面持续朝向镜头。</li><li>小角度环绕，不展示参考图里没有的区域。</li><li>产品运动慢，画面时长控制在一个简单动作内。</li><li>人物与产品分镜生成，最后通过剪辑建立关系。</li></ul><h3 id="高风险镜头" tabindex="-1">高风险镜头 <a class="header-anchor" href="#高风险镜头" aria-label="Permalink to &quot;高风险镜头&quot;">​</a></h3><ul><li>产品高速旋转 180° 或 360°。</li><li>手指长时间遮住 Logo 或包装边缘。</li><li>产品从远景快速变成特写。</li><li>强烈液体、烟雾、粒子穿过包装表面。</li><li>同一镜头同时包含拿起、开盖、倾倒和放下。</li><li>一条 Prompt 里要求多个连续运镜。</li></ul><div class="tip custom-block"><p class="custom-block-title">一个镜头只做一件事</p><p>把“拿起产品、旋转展示、打开包装、倒出内容物”拆成四个短镜头。每条视频只承担一个动作，既能提高包装稳定性，也更方便替换失败镜头。</p></div><h2 id="第四步-正确使用参考图和控制参数" tabindex="-1">第四步：正确使用参考图和控制参数 <a class="header-anchor" href="#第四步-正确使用参考图和控制参数" aria-label="Permalink to &quot;第四步：正确使用参考图和控制参数&quot;">​</a></h2><p>不同工具的名称会变化，但可以按同一原则寻找对应能力：</p><table tabindex="0"><thead><tr><th>能力</th><th>用法</th><th>目的</th></tr></thead><tbody><tr><td>首帧图生视频</td><td>使用已校正的产品关键帧</td><td>锁定初始造型和构图</td></tr><tr><td>主体 / 产品参考</td><td>所有相关镜头使用同一组产品图</td><td>降低跨镜头漂移</td></tr><tr><td>参考强度</td><td>在不过度冻结运动的前提下逐步提高</td><td>增强包装外观约束</td></tr><tr><td>区域遮罩</td><td>保护产品，只生成背景或周围特效</td><td>减少产品区域重绘</td></tr><tr><td>首尾帧控制</td><td>同时约束开始和结束状态</td><td>减少视频末端变形</td></tr><tr><td>运动控制</td><td>用简单、单一的镜头运动</td><td>降低模型自由发挥空间</td></tr></tbody></table><p>参数不要一次改很多。固定 Prompt 和随机种子（工具支持时），每轮只调整一个变量，记录包装稳定性和运动自然度，否则无法判断哪项设置有效。</p><h2 id="第五步-把提示词写成-保真约束-简单运动" tabindex="-1">第五步：把提示词写成“保真约束 + 简单运动” <a class="header-anchor" href="#第五步-把提示词写成-保真约束-简单运动" aria-label="Permalink to &quot;第五步：把提示词写成“保真约束 + 简单运动”&quot;">​</a></h2><p>提示词不能保证包装准确，但可以减少不必要的重新设计。</p><h3 id="通用模板" tabindex="-1">通用模板 <a class="header-anchor" href="#通用模板" aria-label="Permalink to &quot;通用模板&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[景别与构图]，[产品在画面中的位置]。</span></span>
<span class="line"><span>使用参考图中的同一件产品，保持产品外形、包装比例、品牌色、</span></span>
<span class="line"><span>Logo 位置、标签布局和字体结构不变，不新增、删除或改写包装元素。</span></span>
<span class="line"><span>[产品只做一个简单动作]，[镜头只做一个简单运动]。</span></span>
<span class="line"><span>[光线与环境]。包装正面持续清晰可见，边缘稳定，无形变，无闪烁。</span></span></code></pre></div><h3 id="英文约束段" tabindex="-1">英文约束段 <a class="header-anchor" href="#英文约束段" aria-label="Permalink to &quot;英文约束段&quot;">​</a></h3><p>部分模型对英文镜头术语响应更稳定时，可把下面一段固定附在每条产品镜头中：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Preserve the exact product shape, packaging proportions, brand colors,</span></span>
<span class="line"><span>logo placement, label layout, and typography structure from the reference image.</span></span>
<span class="line"><span>Do not redesign, replace, add, remove, or rewrite any packaging element.</span></span>
<span class="line"><span>Keep the front label visible, stable, and free from warping or flicker.</span></span></code></pre></div><h3 id="示例-固定产品-镜头推进" tabindex="-1">示例：固定产品，镜头推进 <a class="header-anchor" href="#示例-固定产品-镜头推进" aria-label="Permalink to &quot;示例：固定产品，镜头推进&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>产品中近景，参考图中的饮料瓶直立放在画面中央的金属台面上。</span></span>
<span class="line"><span>保持瓶型、标签比例、品牌色、Logo 位置和包装版式不变，不新增或改写文字。</span></span>
<span class="line"><span>产品保持静止，镜头缓慢向前推进，包装正面始终朝向镜头。</span></span>
<span class="line"><span>冷色环境光，右后方柔和轮廓光，标签清晰，瓶身边缘稳定，无形变、无闪烁。</span></span></code></pre></div><h3 id="不要过度依赖负面提示词" tabindex="-1">不要过度依赖负面提示词 <a class="header-anchor" href="#不要过度依赖负面提示词" aria-label="Permalink to &quot;不要过度依赖负面提示词&quot;">​</a></h3><p><code>不要变形、不要改字、不要换 Logo</code> 可以降低部分错误，但无法把生成过程变成精确的图层变换。连续补充十几条负面词，通常不如简化动作、缩短镜头和后期贴图有效。</p><h2 id="第六步-什么时候停止重生成" tabindex="-1">第六步：什么时候停止重生成 <a class="header-anchor" href="#第六步-什么时候停止重生成" aria-label="Permalink to &quot;第六步：什么时候停止重生成&quot;">​</a></h2><p>出现下面任一情况，就应评估转入后期，而不是继续抽取新结果：</p><ul><li>包装有必须逐字准确的小字。</li><li>镜头需要较大角度旋转，但缺少完整多角度素材。</li><li>连续多轮生成都在相同区域发生改字或变形。</li><li>产品与手、头发、液体存在复杂遮挡。</li><li>客户要求与包装设计稿逐项核对。</li><li>重生成成本已经高于跟踪与合成成本。</li></ul><p>一个实用原则：<strong>生成阶段优先挑运动和光影最好的版本，不要因为标签错误放弃一个结构稳定的镜头。</strong> 标签可以替换，错误的运动轨迹和遮挡关系更难修。</p><h2 id="三种后期兜底方案" tabindex="-1">三种后期兜底方案 <a class="header-anchor" href="#三种后期兜底方案" aria-label="Permalink to &quot;三种后期兜底方案&quot;">​</a></h2><h3 id="方案一-平面跟踪贴图" tabindex="-1">方案一：平面跟踪贴图 <a class="header-anchor" href="#方案一-平面跟踪贴图" aria-label="Permalink to &quot;方案一：平面跟踪贴图&quot;">​</a></h3><p>适合正面标签接近平面、旋转角度不大的瓶、盒、袋。</p><ol><li>跟踪包装表面的平移、缩放、旋转和透视。</li><li>将包装设计稿或真实标签覆盖到跟踪平面。</li><li>恢复原画面的高光、阴影、运动模糊和景深。</li><li>有遮挡时制作前景遮罩，让手指或液体回到标签前方。</li></ol><h3 id="方案二-局部逐帧修复" tabindex="-1">方案二：局部逐帧修复 <a class="header-anchor" href="#方案二-局部逐帧修复" aria-label="Permalink to &quot;方案二：局部逐帧修复&quot;">​</a></h3><p>适合只有少数帧闪烁、Logo 偶尔变形的短镜头。先选一帧准确包装作为基准，再对问题帧做局部替换和时序检查。它不适合全程大幅变形，否则人工成本会迅速上升。</p><h3 id="方案三-3d-产品替换" tabindex="-1">方案三：3D 产品替换 <a class="header-anchor" href="#方案三-3d-产品替换" aria-label="Permalink to &quot;方案三：3D 产品替换&quot;">​</a></h3><p>适合 360° 旋转、复杂透视、强反光或多角度产品展示。建立瓶体或包装模型，使用真实设计稿作为材质，再匹配 AI 视频中的相机、光线和遮挡。对于高要求产品英雄镜头，这是最稳定的方案。</p><h2 id="跨镜头一致性怎么控制" tabindex="-1">跨镜头一致性怎么控制 <a class="header-anchor" href="#跨镜头一致性怎么控制" aria-label="Permalink to &quot;跨镜头一致性怎么控制&quot;">​</a></h2><p>包装在单条视频里稳定，不代表不同镜头之间就一致。项目层面还要固定以下内容：</p><table tabindex="0"><thead><tr><th>固定项</th><th>记录内容</th></tr></thead><tbody><tr><td>产品资产</td><td>文件名、包装版本、规格、多角度参考图</td></tr><tr><td>主参考图</td><td>所有镜头统一使用的首选参考</td></tr><tr><td>固定描述</td><td>产品外形和包装约束段，逐字复用</td></tr><tr><td>光线规则</td><td>主光方向、色温倾向、轮廓光强弱</td></tr><tr><td>镜头规则</td><td>产品可旋转的最大角度、允许的遮挡范围</td></tr><tr><td>生成记录</td><td>工具、模型版本、参数、种子、成功与失败原因</td></tr></tbody></table><p>产品资产或固定描述发生变化时，要明确创建新版本，不要直接覆盖旧文件。否则后续很难解释为什么补生成的镜头与前一批不一致。</p><h2 id="交付前检查表" tabindex="-1">交付前检查表 <a class="header-anchor" href="#交付前检查表" aria-label="Permalink to &quot;交付前检查表&quot;">​</a></h2><h3 id="产品结构" tabindex="-1">产品结构 <a class="header-anchor" href="#产品结构" aria-label="Permalink to &quot;产品结构&quot;">​</a></h3><ul><li>[ ] 瓶型、盒型或袋型比例正确。</li><li>[ ] 封口、瓶盖、开口和边缘结构没有凭空变化。</li><li>[ ] 产品在镜头中没有忽大忽小或局部融化。</li></ul><h3 id="包装内容" tabindex="-1">包装内容 <a class="header-anchor" href="#包装内容" aria-label="Permalink to &quot;包装内容&quot;">​</a></h3><ul><li>[ ] Logo 的文字、图形、位置和比例准确。</li><li>[ ] 品名、规格、卖点文字没有错字或乱码。</li><li>[ ] 主视觉、色块、图案和标签边界没有漂移。</li><li>[ ] 没有出现不存在的认证标、条码或装饰元素。</li></ul><h3 id="时间一致性" tabindex="-1">时间一致性 <a class="header-anchor" href="#时间一致性" aria-label="Permalink to &quot;时间一致性&quot;">​</a></h3><ul><li>[ ] 逐帧查看时没有闪烁、跳变和瞬间换包装。</li><li>[ ] 视频最后半秒没有常见的末端变形。</li><li>[ ] 运动模糊期间仍能维持正确的品牌色和轮廓。</li></ul><h3 id="商业与品牌" tabindex="-1">商业与品牌 <a class="header-anchor" href="#商业与品牌" aria-label="Permalink to &quot;商业与品牌&quot;">​</a></h3><ul><li>[ ] 使用的是客户确认的最新包装版本。</li><li>[ ] 包装颜色与品牌标准色在可接受范围内。</li><li>[ ] 法务要求保留的信息完整且可读。</li><li>[ ] 生成内容和后期修改均有版本记录。</li></ul><h2 id="最后记住这一句" tabindex="-1">最后记住这一句 <a class="header-anchor" href="#最后记住这一句" aria-label="Permalink to &quot;最后记住这一句&quot;">​</a></h2><blockquote><p><strong>模型负责把产品拍得有想象力，合成负责让产品保持准确。</strong></p></blockquote><p>包装只需“大致像”时，参考图、简单动作和图生视频足够；包装必须商用准确时，从项目开始就把平面跟踪、贴图或 3D 替换写进制作方案，不要把成败押在反复生成上。</p><h2 id="接着看" tabindex="-1">接着看 <a class="header-anchor" href="#接着看" aria-label="Permalink to &quot;接着看&quot;">​</a></h2><ul><li>把复杂动作拆成可生成的镜头 → <a href="/method/storyboard">分镜设计：镜头语言翻译表</a></li><li>了解生成与合成在全流程中的分工 → <a href="/method/workflow-sop">从 brief 到成片：完整链路 SOP</a></li><li>组织每条视频 Prompt → <a href="/prompts/structure">Prompt 结构通法</a></li></ul>`,80)])])}const b=t(n,[["render",s]]);export{u as __pageData,b as default};
